    // howItWorks sources: **已核实为「这一档只能到普查年」**：喀什市、和田市、巴楚县、麦盖提县、漠河市的年度统计公报**根本没有人口章节**（前几批已逐页核对全文确认），能确认的最新官方常住人口就是 2020 年第七次全国人口普查数。
    //   本次改动只是把口径写明确（「2020 年」→「2020 年第七次全国人口普查」）—— 数字一个没动，改的是**让读者知道这是普查数、而不是一个不知从哪来的旧估计**，同时也让 check:claims 的普查例外能正确认出它。
