    //   楠溪江风景名胜区包括八大景区八百多个景点，以火山岩地貌、楠溪江水系和古村落古民居为代表（温州市文广旅局网站 2018-06-23，1 级）。河长各处自相矛盾，不写。
    //   结构（按坐标算）：县城北城街道在瓯江北岸，距温州鹿城直线约 16 km；岩头镇距县城 20 km 以上；芙蓉古村距岩头镇约 1.0 km、苍坡古村约 2.8 km、石桅岩东约 17 km；温州龙湾 WNZ 距岩头约 49 km、距县城约 32 km；温州北站在县境南部，距县城约 9.6 km。
