    identity:
      "永嘉是浙江温州市下辖的一个县，在瓯江北岸，县城就在温州市区隔江对面。县境内有楠溪江流过，楠溪江1988年由国务院批为国家级风景名胜区，江边的岩头镇是中国历史文化名镇，镇边有芙蓉、苍坡等古村。按永嘉县统计局数据，2025年末全县常住人口约88.7万、户籍人口约97.3万。",
    howItWorks:
      "永嘉有两个「中心」：县政府所在的北城街道在瓯江北岸，和温州市区隔江相望，是温州的近郊；游客要去的楠溪江古村却在县城以北二十多公里的岩头镇一带，两者不是一回事。按温州市文广旅局的介绍，楠溪江风景名胜区包括八大景区、八百多个景点，古村落是有人居住的村庄，不是一整片统一售票的古镇景区。人口结构也有特点：2025年末户籍人口比常住人口多出约8.6万，意味着有大量永嘉人在外地工作经商。生活半径由瓯江和楠溪江决定：县城靠温州，古村沿江分布在一条条山谷里。初来的人最容易犯的错，是以为到了永嘉县城就到了楠溪江，其实还要沿江往北走二十多公里的山路。",
    layout:
      "县城北城街道在县境南端的瓯江边，温州北站也在县境南部；沿楠溪江往北约二十多公里是岩头镇，丽水古街在镇上，芙蓉古村在镇南约1公里、苍坡古村在镇北约3公里；石桅岩在岩头镇以东约17公里的山里。以上均为直线距离。",
    gettingAround:
      "永嘉县内没有民用机场，最近的是温州龙湾机场（WNZ，距县城直线约32公里、距岩头镇约49公里）。温州北站在县境南部，离县城直线约10公里。从县城或温州去岩头镇、各古村，坐班车或包车；古村之间距离不远，但山区公交班次少。属亚热带季风气候，夏季有台风和暴雨，雨后溪水上涨。",
    culture:
      "当地说永嘉话（属吴语瓯江片），普通话通行。古村里住着村民，祠堂、民居进门先问。不给小费。",
    seeAndDo:
      "岩头镇的丽水古街；芙蓉古村、苍坡古村；楠溪江沿岸风光；石桅岩；沿江山谷里的古村与田园。",
    whenAndTips:
      "春秋两季最舒服；夏季适合玩水，但台风和暴雨期间山区道路与溪流有风险，出行前看预警。景区门票与开放安排以景区官方公布为准。",
